function isBipartite(graph) {
  const color = {};
  for (const start in graph) {
    if (color[start] !== undefined) continue;
    const queue = [start];
    color[start] = 0;
    while (queue.length) {
      const node = queue.shift();
      for (const next of graph[node]) {
        if (color[next] === undefined) {
          color[next] = 1 - color[node];
          queue.push(next);
        } else if (color[next] === color[node]) {
          return false;
        }
      }
    }
  }
  return true;
}

const graph = { 0: [1, 3], 1: [0, 2], 2: [1, 3], 3: [0, 2] };
console.log(isBipartite(graph));

